import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"2.3 Draft, approve, and write externally","description":"Draft first, approve second, and execute an external write only once.","frontmatter":{"title":"2.3 Draft, approve, and write externally","description":"Draft first, approve second, and execute an external write only once.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-2/2-3.md","filePath":"en/delivery/stage-2/2-3.md","lastUpdated":1794015952000}'),n={name:"en/delivery/stage-2/2-3.md"};function i(l,e,s,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_2-3-draft-approve-and-write-externally" tabindex="-1">2.3 Draft, approve, and write externally <a class="header-anchor" href="#_2-3-draft-approve-and-write-externally" aria-label="Permalink to &quot;2.3 Draft, approve, and write externally&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented:</strong> Drafts can be edited, saved, and discarded; submission creates a one-time, short-lived approval; approval writes to the local outbox through the effect ledger and stores a receipt; rejection or expiry updates the draft state.</li><li><strong>Still open:</strong> Writes go only to the local <code>.hearth/outbox</code> file and do not connect to a mail server; calendar and other external-system writes are not implemented.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let Hearth send email, change a calendar, or write to another work system after the user confirms, and ensure the same operation is not executed twice. Prove it with a test account before touching a real account.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Generate a draft first; do not send directly. The draft can be edited, saved, or discarded.</li><li>The approval page must show the exact target, account, content, attachments, impact, and whether the action can be undone.</li><li>Approval is valid only for a short time and only once; nothing runs after the user declines.</li><li>Use a test account to complete the full flow: read, draft, approve, send or write, and receipt.</li><li>Keep a receipt after sending or writing; on failure, say whether the action may already have happened and how to check or recover.</li><li>Give the execution only the background information the task truly needs, and show which information was used.</li><li>Do not take over the user&#39;s main account without isolation.</li></ol>',7)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
